<script setup lang="ts">
import { computed,ref,watch } from 'vue'
import { useRoute } from 'vue-router'
import { loadPage,errorText } from '../api/http'
import { kindLabel } from '../api/business'
import { dateTime,sourceRoute,statusLabel } from '../utils/format'
import { useAuthStore } from '../stores/auth'
import type { Row } from '../types'
import RemoteSelect from '../components/RemoteSelect.vue'
import StatusTag from '../components/StatusTag.vue'
const route=useRoute(),auth=useAuthStore(),view=computed(()=>route.meta.stockView as 'inbound'|'outbound'|'balances'|'ledgers'),isDocument=computed(()=>['inbound','outbound'].includes(view.value)),title=computed(()=>({inbound:'入库单',outbound:'出库单',balances:'库存余额',ledgers:'库存流水'}[view.value]))
const rows=ref<Row[]>([]),loading=ref(false),error=ref(''),page=ref(1),total=ref(0),q=ref(''),warehouseId=ref(''),materialId=ref(''),status=ref(''),kind=ref(''),type=ref(''),lowStockOnly=ref(false),enabled=ref(true),dates=ref<string[]>([])
function source(row:Row){const target=sourceRoute(row.sourceType,row.sourceId);return target&&auth.can(target.permission)?target.path:null}
async function load(){loading.value=true;error.value='';try{const params:Row={page:page.value,size:20,warehouseId:warehouseId.value||undefined};if(view.value!=='ledgers')params.q=q.value||undefined;if(isDocument.value)Object.assign(params,{direction:view.value==='inbound'?'IN':'OUT',status:status.value||undefined,kind:kind.value||undefined});else params.materialId=materialId.value||undefined;if(view.value==='balances')Object.assign(params,{type:type.value||undefined,lowStockOnly:lowStockOnly.value,enabled:enabled.value});if(view.value!=='balances'&&dates.value?.length===2)Object.assign(params,{from:new Date(dates.value[0]!).toISOString(),to:new Date(dates.value[1]!).toISOString()});const result=await loadPage<Row>(isDocument.value?'/stock-documents':view.value==='balances'?'/stock-balances':'/stock-ledgers',params);rows.value=result.items;total.value=Number(result.total)}catch(e){error.value=errorText(e)}finally{loading.value=false}}
function reset(){q.value='';warehouseId.value='';materialId.value='';status.value='';kind.value='';type.value='';lowStockOnly.value=false;enabled.value=true;dates.value=[];page.value=1;void load()}
watch(()=>[view.value,route.query.status,route.query.lowStockOnly],()=>{status.value=typeof route.query.status==='string'?route.query.status:'';lowStockOnly.value=route.query.lowStockOnly==='true';page.value=1;void load()},{immediate:true})
</script>
<template>
 <div class="page-header"><div><h1>{{title}}</h1></div></div>
 <section class="panel"><form class="filters" @submit.prevent="page=1;load()"><el-input v-if="view!=='ledgers'" v-model="q" placeholder="搜索编号或名称" aria-label="搜索编号或名称" clearable/><RemoteSelect v-if="auth.can('master:warehouse:read')" v-model="warehouseId" resource-path="/warehouses" :active-only="false" placeholder="全部仓库"/><RemoteSelect v-if="!isDocument&&auth.can('master:material:read')" v-model="materialId" resource-path="/materials" :active-only="false" placeholder="全部物料"/><template v-if="isDocument"><el-select v-model="status" clearable placeholder="全部状态" aria-label="库存单状态"><el-option v-for="s in ['PENDING','EXECUTED']" :key="s" :value="s" :label="statusLabel(s)"/></el-select><el-select v-model="kind" clearable placeholder="全部业务类型" aria-label="业务类型"><el-option v-for="k in (view==='inbound'?['PURCHASE_RECEIPT','PRODUCTION_RECEIPT']:['PRODUCTION_ISSUE','SALES_SHIPMENT'])" :key="k" :value="k" :label="kindLabel(k)"/></el-select></template><template v-if="view==='balances'"><el-select v-model="type" clearable placeholder="全部物料类型" aria-label="物料类型"><el-option label="原料" value="RAW_MATERIAL"/><el-option label="成品" value="FINISHED_GOOD"/></el-select><el-select v-model="enabled" aria-label="库存资料状态"><el-option label="启用资料库存" :value="true"/><el-option label="停用资料历史库存" :value="false"/></el-select><el-checkbox v-model="lowStockOnly">仅显示库存预警</el-checkbox></template><el-date-picker v-else v-model="dates" type="datetimerange" start-placeholder="起始时间" end-placeholder="结束时间" aria-label="日期区间"/><el-button type="primary" native-type="submit">查询</el-button><el-button @click="reset">重置</el-button></form>
 <div v-if="error" class="error-box" role="alert">{{error}} <el-button link @click="load">重试</el-button></div>
 <el-table v-loading="loading" :data="rows" :empty-text="`暂无${title}`"><template v-if="isDocument"><el-table-column label="库存单号" min-width="210"><template #default="{row}"><router-link :to="`/wms/${view}/${row.id}`">{{row.documentNo}}</router-link></template></el-table-column><el-table-column label="业务类型" width="140"><template #default="{row}">{{kindLabel(row.kind)}}</template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}"><StatusTag :value="row.status"/></template></el-table-column></template>
 <template v-else><el-table-column prop="materialCode" label="物料编码" min-width="140"/><el-table-column prop="materialName" label="物料名称" min-width="170"/><el-table-column prop="unit" label="单位" width="70"/></template><el-table-column prop="warehouseName" label="仓库" min-width="140"/>
 <template v-if="view==='balances'"><el-table-column label="物料类型" width="100"><template #default="{row}">{{row.type==='RAW_MATERIAL'?'原料':'成品'}}</template></el-table-column><el-table-column prop="quantity" label="当前数量" width="130" align="right"/><el-table-column prop="minStock" label="最低库存" width="130" align="right"/><el-table-column label="预警" width="100"><template #default="{row}"><el-tag :type="row.lowStock?'warning':'success'">{{row.lowStock?'库存不足':'正常'}}</el-tag></template></el-table-column></template>
 <template v-else><template v-if="view==='ledgers'"><el-table-column prop="changeQuantity" label="变动数量" width="120" align="right"/><el-table-column prop="beforeQuantity" label="变动前" width="110" align="right"/><el-table-column prop="afterQuantity" label="变动后" width="110" align="right"/><el-table-column label="库存单" min-width="210"><template #default="{row}"><router-link v-if="auth.can('wms:document:read')" :to="`/wms/${['PURCHASE_RECEIPT','PRODUCTION_RECEIPT'].includes(row.kind)?'inbound':'outbound'}/${row.stockDocumentId}`">{{row.documentNo}}</router-link><span v-else>{{row.documentNo}}</span></template></el-table-column><el-table-column prop="operatorName" label="操作人" width="110"/></template><el-table-column label="业务来源" min-width="200"><template #default="{row}"><router-link v-if="source(row)" :to="source(row)!">{{row.sourceNo}}</router-link><span v-else>{{row.sourceNo}}</span></template></el-table-column><el-table-column :label="view==='ledgers'?'发生时间':'创建时间'" min-width="180"><template #default="{row}">{{dateTime(row.occurredAt||row.createdAt)}}</template></el-table-column></template>
 </el-table><div class="table-footer"><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total, prev, pager, next" @current-change="load"/></div></section>
</template>
